using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.ConceptDynamics.Coding.PositiveRecoding;

internal sealed class OutSplitNumberedRecodingDocument : IScribeDocumentDefinition
{
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Number rectangular edge fibers for the actual outgoing split.",
        H("Number rectangular edge fibers for the actual outgoing split"),
        Blocks(
            Paragraph(Text("Rect.matrix counts fibers of the endpoint maps and Rect.decode bijects numbered matrix edges with the actual fibers. decode_endpoints and encode_endpoints preserve both endpoints, including empty fibers. For the outgoing split, R records retained partition classes and S records original parallel-edge identities. oldEdgeEquiv and newEdgeEquiv retain both inverse equations.")),
            Paragraph(Text("The rectangular API assumes Fintype A and equivalences I ≃ Fin n, J ≃ Fin m. The outgoing part uses finite V,E,L and DecidableEq V,L; topological path numbering also uses discrete topological E,L. Restricting oldEdgeEquiv and newEdgeEquiv to their endpoint fibers derives cardinality and emptiness consequences by Fintype.card_congr and card_eq_zero_iff, including Fin 0. The anonymous Rect Fintype instance supplies infrastructure. numbered_recoding identifies the original positive (R,S) homeomorphism exactly with outgoing lift.")),
            Paragraph(Text("These constructions and identities are repository-derived. Their provenance does not assert literature novelty.")),
            Describe.Lean(DescribeId.Create("positive-recoding-outsplitnumberedrecoding-decode"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/OutSplitNumberedRecoding.decode"), H("decode"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Decode a numbered matrix edge into the actual element of its endpoint fiber, with inverse encoding. Empty fibers remain empty."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("positive-recoding-outsplitnumberedrecoding-old-edge-equiv"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/OutSplitNumberedRecoding.oldEdgeEquiv"), H("oldEdgeEquiv"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Numbering of the actual old edges by RS, not an assumed order match."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("positive-recoding-outsplitnumberedrecoding-new-edge-equiv"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/OutSplitNumberedRecoding.newEdgeEquiv"), H("newEdgeEquiv"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Decode the ranked SR product edges as actual outgoing-split edges. The equivalence preserves each parallel-edge identity."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("positive-recoding-outsplitnumberedrecoding-numbered-recoding"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/OutSplitNumberedRecoding.numbered_recoding"), H("numbered_recoding"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Decoding the EXISTING numbered positive elementary recoding is exactly the actual outgoing partition lift. There is no shift or inverse substitution."))), DescribeRole.Theorem),
            Describe.Remark(DescribeId.Create("positive-recoding-outsplitnumberedrecoding-endpoints"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/OutSplitNumberedRecoding.endpoints"), H("endpoints"), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Record the chosen finite source and target indices of each actual edge. These indices define the rectangular endpoint fibers.")))),
            Describe.Remark(DescribeId.Create("positive-recoding-outsplitnumberedrecoding-fibre"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/OutSplitNumberedRecoding.Fibre"), H("Fibre"), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Retain all edges with the specified numbered endpoints as a subtype. Its cardinality determines the corresponding matrix coefficient.")))),
            Describe.Remark(DescribeId.Create("positive-recoding-outsplitnumberedrecoding-matrix"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/OutSplitNumberedRecoding.matrix"), H("matrix"), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Count each endpoint fiber. The entries are nonnegative multiplicities, including zero for an empty fiber.")))),
            Describe.Remark(DescribeId.Create("positive-recoding-outsplitnumberedrecoding-decode-endpoints"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/OutSplitNumberedRecoding.decode_endpoints"), H("decode_endpoints"), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Decoding a numbered edge preserves its source and target indices. This makes the fiber enumeration compatible with graph incidence.")))),
            Describe.Remark(DescribeId.Create("positive-recoding-outsplitnumberedrecoding-encode-endpoints"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/OutSplitNumberedRecoding.encode_endpoints"), H("encode_endpoints"), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Encoding an actual edge recovers its two chosen endpoint indices. This is the reverse incidence check for the same enumeration.")))),
            
            Describe.Remark(DescribeId.Create("positive-recoding-outsplitnumberedrecoding-old-number"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/OutSplitNumberedRecoding.oldNumber"), H("oldNumber"), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Number the original finite vertex type. This is the old coordinate system for the outgoing factorization.")))),
            Describe.Remark(DescribeId.Create("positive-recoding-outsplitnumberedrecoding-new-number"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/OutSplitNumberedRecoding.newNumber"), H("newNumber"), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Number the actual outgoing-split vertices with their retained class labels. The class information is preserved in the new coordinates.")))),
            Describe.Remark(DescribeId.Create("positive-recoding-outsplitnumberedrecoding-r"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/OutSplitNumberedRecoding.R"), H("R"), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("R half-edges are the retained partition classes themselves.")))),
            Describe.Remark(DescribeId.Create("positive-recoding-outsplitnumberedrecoding-s"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/OutSplitNumberedRecoding.S"), H("S"), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("S half-edges are original edges, including every parallel identity.")))),
            Describe.Remark(DescribeId.Create("positive-recoding-outsplitnumberedrecoding-r-decode"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/OutSplitNumberedRecoding.rDecode"), H("rDecode"), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Decode an R half-edge as a retained outgoing class. It joins an old vertex to the corresponding split vertex.")))),
            Describe.Remark(DescribeId.Create("positive-recoding-outsplitnumberedrecoding-s-decode"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/OutSplitNumberedRecoding.sDecode"), H("sDecode"), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Decode an S half-edge as an original edge in the retained class. Its target is the old target vertex.")))),
            Describe.Remark(DescribeId.Create("positive-recoding-outsplitnumberedrecoding-old-endpoints"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/OutSplitNumberedRecoding.old_endpoints"), H("old_endpoints"), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("The RS edge decoding preserves both original numbered endpoints. This identifies the original graph in the factorization.")))),
            Describe.Remark(DescribeId.Create("positive-recoding-outsplitnumberedrecoding-new-endpoints"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/OutSplitNumberedRecoding.new_endpoints"), H("new_endpoints"), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("The SR edge decoding preserves both outgoing-split numbered endpoints. This identifies the new graph in the factorization.")))),
            
            
            Describe.Remark(DescribeId.Create("positive-recoding-outsplitnumberedrecoding-old-paths"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/OutSplitNumberedRecoding.oldPaths"), H("oldPaths"), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Number every original history through the old edge equivalence and its endpoint laws. This gives the original side of the positive recoding square.")))),
            Describe.Remark(DescribeId.Create("positive-recoding-outsplitnumberedrecoding-new-paths"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/OutSplitNumberedRecoding.newPaths"), H("newPaths"), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Number every outgoing-split history through the new edge equivalence and its endpoint laws. This gives the split side of the same square.")))))));
}
